<div class="page-heading"><div><p class="eyebrow">PERSIAPAN SEBELUM JAM RAMAI</p><h1>Menu & persediaan</h1><p class="page-subtitle">Atur nama, satuan, harga jual, dan jumlah stok.</p></div><a class="button button-primary" href="<?=e(url('products'))?>#productForm">＋ <span>Tambah menu</span></a></div>
<div class="catalog-grid"><section class="panel editor-panel" id="productForm"><div class="panel-head"><div><h2><?=$data['edit']?'Ubah menu':'Menu baru'?></h2><p>Harga dan ketersediaan menu untuk kasir</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=e($data['edit']['id']??0)?>"><label class="span-two">Nama menu<input required name="name" value="<?=e($data['edit']['name']??'')?>" placeholder="Contoh: Cappuccino"></label><label>Kategori<select name="category_id" required><?php foreach($data['categories'] as $c):?><option value="<?=$c['id']?>" <?=($data['edit']['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?><?=$c['status']==='inactive'?' (nonaktif)':''?></option><?php endforeach?></select></label><label>Satuan<input name="unit" maxlength="24" required value="<?=e($data['edit']['unit']??'porsi')?>" placeholder="gelas, porsi, potong"></label><label>Harga jual<input type="number" name="selling_price" min="1" step="500" value="<?=e($data['edit']['selling_price']??'')?>" placeholder="30000" required></label><label>Modal per satuan<input type="number" name="cost_price" min="0" step="500" value="<?=e($data['edit']['cost_price']??0)?>"></label><label>Stok tersedia<input type="number" name="stock" min="0" value="<?=e($data['edit']['stock']??0)?>" required></label><label class="check-line span-two"><input type="checkbox" name="active" <?=(!$data['edit']||$data['edit']['status']==='active')?'checked':''?>> Tampilkan menu ini di kasir</label><div class="form-actions span-two"><?php if($data['edit']):?><a class="button button-quiet" href="<?=e(url('products'))?>">Batal</a><?php endif?><button class="button button-primary"><?=$data['edit']?'Simpan perubahan':'Tambahkan menu'?></button></div></form></section>
<section class="panel category-panel"><div class="panel-head"><div><h2><?=$data['category_edit']?'Ubah kategori':'Kategori menu'?></h2><p>Kelompok agar menu cepat ditemukan</p></div></div><div class="category-list"><?php foreach($data['categories'] as $c):?><div><span><?=$c['status']==='active'?'●':'○'?></span><strong><?=e($c['name'])?></strong><small><?=e(ucfirst($c['status']))?></small><a class="row-link" href="<?=e(url('products',['edit_category'=>$c['id']]))?>#categoryForm">Ubah</a><form method="post" onsubmit="return confirm('Hapus kategori ini? Menu yang masih memakai kategori harus dipindahkan terlebih dahulu.')"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_category"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="text-danger" title="Hapus kategori" aria-label="Hapus kategori <?=e($c['name'])?>">×</button></form></div><?php endforeach?></div><form method="post" class="add-category" id="categoryForm"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=e($data['category_edit']['id']??0)?>"><input name="name" required maxlength="80" value="<?=e($data['category_edit']['name']??'')?>" placeholder="<?=$data['category_edit']?'Nama kategori':'Nama kategori baru'?>"><button class="button button-dark"><?=$data['category_edit']?'Simpan':'Tambah'?></button><?php if($data['category_edit']):?><label class="check-line"><input type="checkbox" name="active" <?=$data['category_edit']['status']==='active'?'checked':''?>> Aktif</label><a class="row-link" href="<?=e(url('products'))?>">Batal</a><?php endif?></form></section></div>
<section class="panel product-table"><div class="panel-head"><div><h2>Daftar menu</h2><p><?=count($data['products'])?> item tercatat</p></div><label class="search-box table-search"><span>⌕</span><input id="tableSearch" placeholder="Cari menu..."></label></div><div class="table-scroll"><table><thead><tr><th>Menu</th><th>Kode</th><th>Kategori</th><th>Satuan</th><th>Harga jual</th><th>Modal</th><th>Stok</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($data['products'] as $p):?><tr data-search-row><td class="product-name-cell"><span class="stock-thumb"><?=e(mb_strtoupper(mb_substr($p['name'],0,1)))?></span><?=e($p['name'])?></td><td class="invoice-cell"><?=e($p['sku'])?></td><td><?=e($p['category'])?></td><td><?=e($p['unit'])?></td><td class="money-cell"><?=rupiah($p['selling_price'])?></td><td><?=rupiah($p['cost_price'])?></td><td><span class="stock-badge <?=$p['stock']<=$config['low_stock_limit']?'stock-critical':''?>"><?=number_format($p['stock'])?></span></td><td><span class="status <?=$p['status']==='active'?'status-completed':'status-cancelled'?>"><?=$p['status']==='active'?'Aktif':'Nonaktif'?></span></td><td><a class="row-link" href="<?=e(url('products',['edit'=>$p['id']]))?>#productForm">Ubah</a></td></tr><?php endforeach?></tbody></table></div></section>
